	. "github.com/onsi/gomega"
)

var _ = Describe("UserPropsRepository", func() {
	var o orm.Ormer
	var firstID, secondID string
	var first, second model.UserPropsRepository

	BeforeEach(func() {
		o = orm.NewOrm()
		firstID, secondID = uuid.NewString(), uuid.NewString()
		for _, id := range []string{firstID, secondID} {
			_, err := o.Raw(`insert into user (id, user_name, name, email, password, created_at, updated_at)
				values (?, ?, ?, ?, '', ?, ?)`, id, id, id, id+"@example.com", time.Now(), time.Now()).Exec()
			Expect(err).ToNot(HaveOccurred())
		}
		ctx := log.NewContext(context.Background())
		first = NewUserPropsRepository(request.WithUser(ctx, model.User{ID: firstID}), o)
		second = NewUserPropsRepository(request.WithUser(ctx, model.User{ID: secondID}), o)
	})

	AfterEach(func() {
		_, err := o.Raw("delete from user_props where user_id in (?, ?)", firstID, secondID).Exec()
		Expect(err).ToNot(HaveOccurred())
		_, err = o.Raw("delete from user where id in (?, ?)", firstID, secondID).Exec()
		Expect(err).ToNot(HaveOccurred())
	})

	It("creates and updates properties within the contextual user", func() {
		Expect(first.Put("key", "first value")).To(Succeed())
		Expect(first.Get("key")).To(Equal("first value"))
		Expect(second.Get("key")).To(Equal("", model.ErrNotFound))

		Expect(second.Put("key", "second value")).To(Succeed())
		Expect(first.Put("key", "updated value")).To(Succeed())
		Expect(first.Get("key")).To(Equal("updated value"))
		Expect(second.Get("key")).To(Equal("second value"))
	})

	It("deletes only the contextual user's property", func() {
		Expect(first.Put("key", "first value")).To(Succeed())
		Expect(second.Put("key", "second value")).To(Succeed())
		Expect(first.Delete("key")).To(Succeed())
		Expect(first.Get("key")).To(Equal("", model.ErrNotFound))
		Expect(second.Get("key")).To(Equal("second value"))
	})

	It("rejects operations without a contextual user", func() {
		unscoped := NewUserPropsRepository(log.NewContext(context.Background()), o)
		Expect(unscoped.Put("key", "value")).To(Equal(model.ErrNotAuthorized))
		Expect(unscoped.Get("key")).To(Equal("", model.ErrNotAuthorized))
		Expect(unscoped.Delete("key")).To(Equal(model.ErrNotAuthorized))
	})
})
package tests

import (
	"context"
	"sync"

	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
)

// MockUserPropsRepo stores properties separately for each contextual user.
type MockUserPropsRepo struct {
	ctx   context.Context
	store *mockUserPropsStore
}

type mockUserPropsStore struct {
	mu     sync.Mutex
	values map[string]map[string]string
}

func NewMockUserPropsRepo(ctx context.Context) *MockUserPropsRepo {
	return &MockUserPropsRepo{ctx: ctx, store: &mockUserPropsStore{values: make(map[string]map[string]string)}}
}

// WithContext returns a repository for another user while sharing stored values.
func (r *MockUserPropsRepo) WithContext(ctx context.Context) *MockUserPropsRepo {
	return &MockUserPropsRepo{ctx: ctx, store: r.store}
}

func (r *MockUserPropsRepo) userID() (string, error) {
	user, ok := request.UserFrom(r.ctx)
	if !ok || user.ID == "" {
		return "", model.ErrNotAuthorized
	}
	return user.ID, nil
}

func (r *MockUserPropsRepo) Put(key, value string) error {
	userID, err := r.userID()
	if err != nil {
		return err
	}
	r.store.mu.Lock()
	defer r.store.mu.Unlock()
	if r.store.values[userID] == nil {
		r.store.values[userID] = make(map[string]string)
	}
	r.store.values[userID][key] = value
	return nil
}

func (r *MockUserPropsRepo) Get(key string) (string, error) {
	userID, err := r.userID()
	if err != nil {
		return "", err
	}
	r.store.mu.Lock()
	defer r.store.mu.Unlock()
	value, ok := r.store.values[userID][key]
	if !ok {
		return "", model.ErrNotFound
	}
	return value, nil
}

func (r *MockUserPropsRepo) Delete(key string) error {
	userID, err := r.userID()
	if err != nil {
		return err
	}
	r.store.mu.Lock()
	defer r.store.mu.Unlock()
	if _, ok := r.store.values[userID][key]; !ok {
		return model.ErrNotFound
	}
	delete(r.store.values[userID], key)
	return nil
}

