package migrations

import (
	"database/sql"
	"testing"

	_ "github.com/mattn/go-sqlite3"
)

func TestCreateUserPropsTableMovesLastFMSessions(t *testing.T) {
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1)

	_, err = db.Exec(`
		pragma foreign_keys = on;
		create table user (id text primary key);
		create table property (id text primary key, value text not null);
		insert into user (id) values ('user_1'), ('user-2');
		insert into property (id, value) values
			('LastFMSessionKey_user_1', 'first session'),
			('LastFMSessionKey_user-2', 'second session'),
			('LastFMSessionKey_deleted-user', 'orphan session'),
			('LastScan', 'global value');
	`)
	if err != nil {
		t.Fatal(err)
	}

	tx, err := db.Begin()
	if err != nil {
		t.Fatal(err)
	}
	if err = upCreateUserPropsTable(tx); err != nil {
		_ = tx.Rollback()
		t.Fatal(err)
	}
	if err = tx.Commit(); err != nil {
		t.Fatal(err)
	}

	for _, tc := range []struct{ userID, value string }{
		{"user_1", "first session"},
		{"user-2", "second session"},
	} {
		var value string
		if err := db.QueryRow("select value from user_props where user_id = ? and key = ?", tc.userID, "LastFMSessionKey").Scan(&value); err != nil {
			t.Fatal(err)
		}
		if value != tc.value {
			t.Errorf("session for %s = %q, want %q", tc.userID, value, tc.value)
		}
	}

	var count int
	if err := db.QueryRow("select count(*) from property where id in ('LastFMSessionKey_user_1', 'LastFMSessionKey_user-2')").Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Errorf("migrated global session properties remaining: %d", count)
	}
	if err := db.QueryRow("select count(*) from property where id in ('LastScan', 'LastFMSessionKey_deleted-user')").Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Errorf("unrelated or orphan properties remaining: %d, want 2", count)
	}

	if _, err := db.Exec("delete from user where id = 'user-2'"); err != nil {
		t.Fatal(err)
	}
	if err := db.QueryRow("select count(*) from user_props where user_id = 'user-2'").Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Errorf("properties remaining after user deletion: %d", count)
	}
}
package persistence

import (
	"context"
	"time"

	"github.com/astaxie/beego/orm"
	"github.com/google/uuid"
	"github.com/navidrome/navidrome/log"
	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/model/request"
	. "github.com/onsi/ginkgo"
	. "github.com/onsi/gomega"
)

var _ = Describe("UserPropsRepository", func() {
	var o orm.Ormer
	var firstID, secondID string
	var first, second model.UserPropsRepository

	BeforeEach(func() {
		o = orm.NewOrm()
		firstID, secondID = uuid.NewString(), uuid.NewString()
		for _, id := range []string{firstID, secondID} {
			_, err := o.Raw(`insert into user (id, user_name, name, email, password, created_at, updated_at)
				values (?, ?, ?, ?, '', ?, ?)`, id, id, id, id+"@example.com", time.Now(), time.Now()).Exec()
			Expect(err).ToNot(HaveOccurred())
		}
		ctx := log.NewContext(context.Background())
		first = NewUserPropsRepository(request.WithUser(ctx, model.User{ID: firstID}), o)
		second = NewUserPropsRepository(request.WithUser(ctx, model.User{ID: secondID}), o)
	})

	AfterEach(func() {
		_, err := o.Raw("delete from user_props where user_id in (?, ?)", firstID, secondID).Exec()
		Expect(err).ToNot(HaveOccurred())
		_, err = o.Raw("delete from user where id in (?, ?)", firstID, secondID).Exec()
		Expect(err).ToNot(HaveOccurred())
	})

	It("creates and updates properties within the contextual user", func() {
		Expect(first.Put("key", "first value")).To(Succeed())
		Expect(first.Get("key")).To(Equal("first value"))
		value, err := second.Get("key")
		Expect(value).To(BeEmpty())
		Expect(err).To(Equal(model.ErrNotFound))

		Expect(second.Put("key", "second value")).To(Succeed())
		Expect(first.Put("key", "updated value")).To(Succeed())
		Expect(first.Get("key")).To(Equal("updated value"))
		Expect(second.Get("key")).To(Equal("second value"))
	})

	It("deletes only the contextual user's property", func() {
		Expect(first.Put("key", "first value")).To(Succeed())
		Expect(second.Put("key", "second value")).To(Succeed())
		Expect(first.Delete("key")).To(Succeed())
		value, err := first.Get("key")
		Expect(value).To(BeEmpty())
		Expect(err).To(Equal(model.ErrNotFound))
		Expect(second.Get("key")).To(Equal("second value"))
	})

	It("rejects operations without a contextual user", func() {
		unscoped := NewUserPropsRepository(log.NewContext(context.Background()), o)
		Expect(unscoped.Put("key", "value")).To(Equal(model.ErrNotAuthorized))
		value, err := unscoped.Get("key")
		Expect(value).To(BeEmpty())
		Expect(err).To(Equal(model.ErrNotAuthorized))
		Expect(unscoped.Delete("key")).To(Equal(model.ErrNotAuthorized))
	})
})
